#!/bin/sh
# Cloudflare Pages build: copy only the files the game needs into dist/ (so firebase.json, firestore.rules,
# the GitHub workflows and the README are not published). Pages settings: build command "sh build-cloudflare.sh",
# output directory "dist".
set -e
rm -rf dist
mkdir dist
cp index.html sw.js manifest.webmanifest icon.svg apple-touch-icon.png icon-192.png icon-512.png _headers dist/
cp -r data dist/data
cp -r help dist/help
# the static pages (generated by tools/build-pages.js and committed) and the files search engines look for
cp -r how-to-play dist/how-to-play
cp -r privacy dist/privacy
cp -r terms dist/terms
cp robots.txt sitemap.xml dist/
# safety net: the legal pages carry a placeholder until the real contact address is set (CONTACT_EMAIL when running
# tools/build-pages.js). A production build (the main branch) with the placeholder still in it fails, so the site
# that is live stays as it is; preview builds of other branches are unaffected.
if [ "$CF_PAGES_BRANCH" = "main" ] && grep -rl "CONTACT_EMAIL_HERE" dist >/dev/null 2>&1; then
  echo "ERROR: CONTACT_EMAIL_HERE is still in the pages: run CONTACT_EMAIL=you@example.com node tools/build-pages.js and commit." >&2
  exit 1
fi
# version.json: the game compares it with its own APP_VERSION to offer an update to a copy left open (see checkForUpdate)
ver=$(grep -o "const APP_VERSION = '[0-9.]*'" index.html | head -1 | grep -o "[0-9][0-9.]*")
printf '{"version":"%s"}\n' "$ver" > dist/version.json
cat dist/version.json
echo "dist/ ready:"
ls -la dist dist/data
